const Effects={hit(n){let e=document.createElement("div");e.className="hit";e.textContent="-"+n;let c=document.getElementById("canvas");e.style.left=(35+Math.random()*35)+"%";e.style.top=(38+Math.random()*20)+"%";c.parentElement.appendChild(e);setTimeout(()=>e.remove(),650)},money(n){let e=document.createElement("div");e.className="fish-float";e.textContent="+"+n+"💰";e.style.left="55%";e.style.bottom="170px";document.body.appendChild(e);setTimeout(()=>e.remove(),1000)}};